SELECT ,
       (SELECT COUNT(*) FROM wms_check_item ci WHERE ci.check_id = c.id) AS item_count,
       (SELECT COUNT(*) FROM wms_check_item ci WHERE ci.check_id = c.id
           AND ci.actual_qty IS NOT NULL AND ci.actual_qty <> ci.book_qty) AS diff_count


    c.doc_no LIKE CONCAT('%', #{q.docNo}, '%')
    AND c.warehouse_id = #{q.warehouseId}
    AND c.status = #{q.status}
    AND c.biz_date >= #{q.beginDate}
    AND c.biz_date <= #{q.endDate}

ORDER BY c.id DESC
